import java.util.logging.*;

public class SLF4JPattern {
    static final Logger log = Logger.getLogger("Demo");
    static {
        log.setUseParentHandlers(false);
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.INFO);
        log.addHandler(h);
        log.setLevel(Level.INFO);
    }
    public static void main(String[] args) {
        String user = "Eldrin";
        log.info(String.format("User %s logged in", user));  // appears
        log.fine("Debug detail — should not appear");          // filtered
        log.warning("Low mana warning");                        // appears
        System.out.println("Logging demo complete");
    }
}
